const $=s=>document.querySelector(s), key='averagecost-v1', icons={Car:'🚙',Phone:'▯',Laptop:'▱',Home:'⌂',Other:'◇'};
let state={items:[],currency:'AUD'}, filter='All',editing=null,selected=null;
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&Array.isArray(saved.items))state=saved}catch(e){}
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}, day=s=>Date.parse(s+'T00:00:00Z'), days=(a,b)=>Math.floor((day(b)-day(a))/86400000)+1;
const money=n=>new Intl.NumberFormat('en-AU',{style:'currency',currency:state.currency}).format(n), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function payments(e,asof=today()){let end=e.end&&e.end<asof?e.end:asof;if(end<e.date)return 0;let n=days(e.date,end);if(e.frequency==='once')return 1;if(e.frequency==='daily')return n;if(e.frequency==='weekly')return Math.floor((n-1)/7)+1;let start=new Date(day(e.date)), finish=new Date(day(end)), interval=e.frequency==='yearly'?12:1;let months=(finish.getUTCFullYear()-start.getUTCFullYear())*12+finish.getUTCMonth()-start.getUTCMonth();let count=Math.floor(months/interval);const y=start.getUTCFullYear(),m=start.getUTCMonth()+count*interval;const due=new Date(Date.UTC(y,m,Math.min(start.getUTCDate(),new Date(Date.UTC(y,m+1,0)).getUTCDate())));return Math.max(0,count+(due<=finish?1:0))}
function calc(i){const expenses=i.expenses.reduce((s,e)=>s+e.amount*payments(e),0),owned=Math.max(1,days(i.date,today()));return{expenses,total:i.price+expenses,owned,daily:(i.price+expenses)/owned}}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch(e){toast('Storage is unavailable. Export a backup before leaving.')}render()}
function render(){const totals=state.items.reduce((s,i)=>{const c=calc(i);return{daily:s.daily+c.daily,total:s.total+c.total}},{daily:0,total:0});$('#daily').innerHTML=money(totals.daily)+'<span>/ day</span>';$('#invested').textContent=money(totals.total);$('#count').innerHTML=state.items.length+' <small>items</small>';$('#badge').textContent=state.items.length;$('#today').textContent=new Date().toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric'});$('#currency').value=state.currency;$('#filters').innerHTML=['All','Car','Phone','Laptop','Home','Other'].map(c=>`<button data-filter="${c}" class="${filter===c?'active':''}">${c==='All'?'All items':c}</button>`).join('');let items=state.items.filter(i=>(filter==='All'||i.category===filter)&&i.name.toLowerCase().includes($('#search').value.toLowerCase()));items.sort((a,b)=>$('#sort').value==='name'?a.name.localeCompare(b.name):$('#sort').value==='new'?b.date.localeCompare(a.date):calc(b).daily-calc(a).daily);$('#items').innerHTML=items.map(i=>{const c=calc(i);return `<button class="card" data-item="${esc(i.id)}"><div class="card-top"><span class="icon">${icons[i.category]||'◇'}</span><span class="pill">${esc(i.category)}</span></div><h3>${esc(i.name)}</h3><div class="owned">Owned for ${c.owned.toLocaleString()} days · Since ${new Date(day(i.date)).toLocaleDateString('en-AU',{month:'short',year:'numeric',timeZone:'UTC'})}</div><div class="card-price">${money(c.daily)} <small>/ day</small></div><div class="owned">${money(c.total)} invested in total</div><div class="track"><i style="width:${c.total?i.price/c.total*100:0}%"></i></div><div class="card-bottom"><span>Purchase ${money(i.price)}</span><span>Expenses ${money(c.expenses)}</span></div></button>`}).join('')||`<div class="empty"><span class="icon" style="margin:auto">＋</span><h3>${state.items.length?'No matching items':'Your collection starts here.'}</h3><p>${state.items.length?'Try another search or category.':'Add your car, phone, laptop, or anything you want to understand better.'}</p>${state.items.length?'':'<button class="primary" id="first">Add your first item</button>'}</div>`;$('#first')?.addEventListener('click',()=>openEditor())}
function openEditor(id=null){editing=id;const f=$('#itemForm');f.reset();$('#formTitle').textContent=id?'Edit item':'Add an item';const i=state.items.find(i=>i.id===id);if(i)for(const k of ['name','price','date','category','notes'])f.elements[k].value=i[k]||'';else f.elements.date.value=today();f.elements.date.max=today();$('#editor').showModal()}
function detail(id){selected=id;const i=state.items.find(i=>i.id===id);if(!i)return;const c=calc(i);$('#detail').innerHTML=`<div class="modal-top"><h2>${icons[i.category]||'◇'} ${esc(i.name)}</h2><button class="close" data-close>×</button></div><div class="detail-number">${money(c.daily)} <small>/ day</small></div><p class="muted">${c.owned.toLocaleString()} days owned · Purchased ${esc(i.date)}</p>${i.notes?`<p>${esc(i.notes)}</p>`:''}<div class="detail-stats"><div>Purchase<strong>${money(i.price)}</strong></div><div>Expenses to date<strong>${money(c.expenses)}</strong></div><div>Total invested<strong>${money(c.total)}</strong></div></div><div class="section-title"><h3>Expenses</h3><button id="addExpense">＋ Add expense</button></div>${i.expenses.length?i.expenses.map(e=>`<div class="expense-row"><div>${esc(e.name)}<small>${money(e.amount)} · ${esc(e.frequency)} · From ${esc(e.date)}${e.end?' to '+esc(e.end):''}<br>${payments(e)} payment(s) through today</small></div><div><strong>${money(e.amount*payments(e))}</strong><button class="danger" data-delete-expense="${esc(e.id)}" aria-label="Delete expense">×</button></div></div>`).join(''):'<p class="muted">Add insurance, repairs, parking, or any other cost.</p>'}<div class="modal-actions"><button id="deleteItem" class="danger">Delete item</button><button id="editItem">Edit item</button></div>`;if(!$('#detail').open)$('#detail').showModal();$('#addExpense').onclick=()=>{const f=$('#expenseForm');f.reset();f.elements.date.value=today();f.elements.date.min=i.date;f.elements.date.max=today();$('#expense').showModal()};$('#editItem').onclick=()=>{$('#detail').close();openEditor(id)};$('#deleteItem').onclick=()=>{if(confirm('Delete this item and all its expenses?')){state.items=state.items.filter(x=>x.id!==id);$('#detail').close();save()}}}
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close)close.closest('dialog').close();const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render()}const i=e.target.closest('[data-item]');if(i)detail(i.dataset.item);const d=e.target.closest('[data-delete-expense]');if(d&&confirm('Delete this expense?')){const i=state.items.find(i=>i.id===selected);i.expenses=i.expenses.filter(e=>e.id!==d.dataset.deleteExpense);save();detail(selected)}});
$('#add').onclick=()=>openEditor();$('#method').onclick=()=>$('#explanation').showModal();$('#search').oninput=render;$('#sort').onchange=render;$('#currency').onchange=e=>{state.currency=e.target.value;save();toast('Currency label changed. Amounts are not converted.')};
$('#itemForm').onsubmit=e=>{e.preventDefault();const f=e.target,values=Object.fromEntries(new FormData(f));if(values.date>today())return toast('Purchase date cannot be in the future.');const old=state.items.find(i=>i.id===editing);if(old&&old.expenses.some(e=>e.date<values.date))return toast('Purchase date must be before all expenses.');const item={...values,price:Number(values.price),id:editing||crypto.randomUUID(),expenses:old?.expenses||[]};if(!item.name.trim())return;item.name=item.name.trim();if(editing)state.items[state.items.findIndex(i=>i.id===editing)]=item;else state.items.push(item);$('#editor').close();save();toast('Item saved')};
$('#expenseForm').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target)),i=state.items.find(i=>i.id===selected);if(v.date<i.date||v.date>today())return toast('Choose a date between purchase and today.');if(v.end&&v.end<v.date)return toast('Last payment date must follow the first payment.');i.expenses.push({...v,amount:Number(v.amount),id:crypto.randomUUID()});$('#expense').close();save();detail(selected)};
$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`averagecost-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&Number.isFinite(day(s))&&new Date(day(s)).toISOString().slice(0,10)===s}
function valid(data){return data&&['AUD','USD','HKD','EUR','GBP'].includes(data.currency)&&Array.isArray(data.items)&&data.items.every(i=>typeof i.id==='string'&&typeof i.name==='string'&&i.name.trim()&&Object.keys(icons).includes(i.category)&&Number.isFinite(i.price)&&i.price>=0&&validDate(i.date)&&i.date<=today()&&Array.isArray(i.expenses)&&i.expenses.every(e=>typeof e.id==='string'&&typeof e.name==='string'&&Number.isFinite(e.amount)&&e.amount>0&&['once','daily','weekly','monthly','yearly'].includes(e.frequency)&&validDate(e.date)&&e.date>=i.date&&e.date<=today()&&(!e.end||(validDate(e.end)&&e.end>=e.date))))}
$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{if(!e.target.files[0])return;const data=JSON.parse(await e.target.files[0].text());if(!valid(data))throw Error();if(state.items.length&&!confirm('Replace your current collection with this backup? Export first if you need to keep it.'))return;state=data;filter='All';save();toast('Backup restored')}catch(e){toast('This file is not a valid AverageCost backup.')}finally{$('#file').value=''}};
$('#demo').onclick=()=>{if(state.items.length&&!confirm('Add three clearly labelled sample items to your collection?'))return;const dateOffset=n=>new Date(day(today())-n*86400000).toISOString().slice(0,10);state.items.push(...[{name:'Toyota Corolla · Sample',category:'Car',price:24000,date:dateOffset(900),expenses:[{name:'Insurance',amount:1100,date:dateOffset(900),frequency:'yearly',end:''},{name:'Battery replacement',amount:240,date:dateOffset(120),frequency:'once',end:''}]},{name:'iPhone · Sample',category:'Phone',price:1499,date:dateOffset(500),expenses:[]},{name:'MacBook Air · Sample',category:'Laptop',price:1899,date:dateOffset(700),expenses:[]}].map(i=>({...i,id:crypto.randomUUID(),notes:'Example data — edit or delete this item.',expenses:i.expenses.map(e=>({...e,id:crypto.randomUUID()}))})));save()};
render();setInterval(()=>{render();if($('#detail').open)detail(selected)},60000);
